package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu      sync.Mutex
	tokens  float64
	last    time.Time
	rate    float64 // tokens per second
	burst   int
	clock   Clock
	maxWait time.Duration
}

var (
	ErrRate        = errors.New("ratelimit: rate must be > 0")
	ErrBurst       = errors.New("ratelimit: burst must be > 0")
	ErrMaxWait     = errors.New("ratelimit: maxWait must be non-negative")
	ErrNilClock    = errors.New("ratelimit: clock must not be nil")
	ErrMaxWaitLess = errors.New("ratelimit: maxWait exceeds refill time of full burst")
)

// NewLimiter creates a Limiter with the given refill rate (tokens/sec),
// burst capacity, and maximum time a caller may need to wait for tokens
// (0 means unlimited). A nil clock uses the real clock.
func NewLimiter(rate float64, burst int, maxWait time.Duration, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrRate
	}
	if burst <= 0 {
		return nil, ErrBurst
	}
	if maxWait < 0 {
		return nil, ErrMaxWait
	}
	if maxWait > 0 && time.Duration(float64(time.Second)*float64(burst)/rate) > maxWait {
		return nil, ErrMaxWaitLess
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:  float64(burst),
		last:    clock.Now(),
		rate:    rate,
		burst:   burst,
		clock:   clock,
		maxWait: maxWait,
	}, nil
}

// AllowN reports whether n tokens are available at time now, consuming
// them if so. n must be non-negative.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.advance(now)
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// WaitN blocks until n tokens are available or the required wait would
// exceed maxWait (when maxWait > 0), in which case it returns false
// without consuming tokens. n must be non-negative.
func (l *Limiter) WaitN(n int) bool {
	if n < 0 || n > l.burst {
		return false
	}
	deadline := time.Time{}
	if l.maxWait > 0 {
		deadline = time.Now().Add(l.maxWait)
	}
	for {
		l.mu.Lock()
		now := l.clock.Now()
		l.advance(now)
		if l.tokens >= float64(n) {
			l.tokens -= float64(n)
			l.mu.Unlock()
			return true
		}
		deficit := float64(n) - l.tokens
		wait := time.Duration(deficit / l.rate * float64(time.Second))
		l.mu.Unlock()
		if !deadline.IsZero() && time.Now().Add(wait).After(deadline) {
			return false
		}
		if wait > 0 {
			time.Sleep(wait)
		}
	}
}

// advance refills tokens based on elapsed time since last; caller holds mu.
func (l *Limiter) advance(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.burst), l.tokens+elapsed*l.rate)
		l.last = now
	}
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
