// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. Implementations must be safe for
// concurrent use.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// SystemClock is the default Clock backed by time.Now.
var SystemClock Clock = systemClock{}

// Limiter is a concurrency-safe token-bucket rate limiter. Tokens are
// refilled continuously at rate tokens per second, up to burst capacity.
// The zero value is not usable; construct with New.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    float64 // bucket capacity
	tokens   float64 // available tokens
	lastFill time.Time
	clock    Clock
}

// ErrInvalidConfig is returned by New when rate or burst are not positive.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be > 0")

// New returns a Limiter that admits events at rate tokens per second with
// burst capacity. The bucket starts full. clock may be nil, in which case
// SystemClock is used.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = SystemClock
	}
	return &Limiter{
		rate:     rate,
		burst:    float64(burst),
		tokens:   float64(burst),
		lastFill: clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now according to
// the limiter's rate and burst. It consumes the tokens if allowed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastFill).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.lastFill = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// AllowNNow reports whether n tokens may be consumed at the limiter's
// current time.
func (l *Limiter) AllowNNow(n int) bool {
	return l.AllowN(l.clock.Now(), n)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
