// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock is the production Clock.
var RealClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate Rate tokens per second, up to Burst.
type Limiter struct {
	mu       sync.Mutex
	rate     float64 // tokens per second
	burst    float64 // capacity
	tokens   float64 // current tokens
	last     time.Time
	lastZero time.Time // last time tokens were zero (for future RetryAfter support)
	clock    Clock
}

// NewLimiter creates a Limiter with the given refill rate (tokens/sec) and burst.
// rate must be > 0 and burst must be >= 1.
func NewLimiter(rate float64, burst int) (*Limiter, error) {
	return NewLimiterWithClock(rate, burst, RealClock)
}

// NewLimiterWithClock is like NewLimiter but accepts an injectable Clock.
func NewLimiterWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst < 1 {
		return nil, errors.New("ratelimit: burst must be >= 1")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   now,
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time since last refill.
// Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if now.Before(l.last) {
		now = l.last // guard against clock going backwards
	}
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if l.tokens <= 0 {
		l.lastZero = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		if l.tokens <= 0 {
			l.lastZero = now
		}
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the current number of available tokens (approximate, for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
